<script setup lang="ts">
import {useAttrs,watchPostEffect,onUpdated} from 'vue';import {InputNumber as TInputNumber} from 'tdesign-vue-next';import {useControl,useDisabled} from './control';
defineOptions({inheritAttrs:false});const props=defineProps<{modelValue:number|string|undefined;min?:number;max?:number;step?:number;disabled?:boolean;placeholder?:string}>();const emit=defineEmits<{'update:modelValue':[value:number|string|undefined]}>(),attrs=useAttrs(),disabled=useDisabled(props),{root}=useControl(attrs);
function semantics(){const input=root.value?.querySelector('input');if(input){input.setAttribute('role','spinbutton');input.setAttribute('inputmode','decimal');for(const [name,value] of [['aria-valuemin',props.min],['aria-valuemax',props.max],['aria-valuenow',props.modelValue!==''&&Number.isFinite(Number(props.modelValue))?props.modelValue:undefined]] as const){if(value!==undefined)input.setAttribute(name,String(value));else input.removeAttribute(name);}}root.value?.querySelectorAll('button').forEach((button,index)=>button.setAttribute('aria-label',index===0?'减少数值':'增加数值'));}watchPostEffect(semantics);onUpdated(semantics);
</script>
<template><div ref="root" class="sk-control sk-number" :class="attrs.class"><TInputNumber :value="modelValue" :min="min" :max="max" :step="step||1" :disabled="disabled" :placeholder="placeholder" :allow-input-over-limit="true" theme="row" @change="emit('update:modelValue',$event)"/></div></template>
